insert into public.gathering_scripts (series_id, season_number, week, data) values
('dark-moon', 1, 1, '{"meta":{"dc":8,"ueDc":6,"def":23,"atk":16,"reward":380,"enemy":"Mine Guard","condition":null,"ueAttr":"Might","ueTitle":"THE DROP","barWay":"The Drop","barRisk":"{RISK} HP"},"steps":[{"t":"tonight","text":"Tonight: the Gathering. The map ends across the ford, at the mark from Meira''s rubbing. Tonight calls on Might.","section":""},{"t":"section","title":"Arrival","section":"Arrival"},{"t":"say","text":"Evening finds you where the map said you would be: an old mine cut into the far riverbank, its mouth half drowned by the river.\n\nThere is torchlight just inside. There should not be.\n\nWhile you watch, it moves from one side of the mouth to the other, unhurried, and stops.\n\nGarrick knows a way in. He has known it since he was a boy, he says.","section":"Arrival"},{"t":"section","title":"The Approach","section":"The Approach"},{"t":"pick","vote":true,"question":"HOW DO YOU GO IN?","options":[{"label":"GARRICK''S WAY","desc":"a dry side-passage up the bank. You come in above them."},{"label":"THE DROWNED MOUTH","desc":"waist-deep, with the river loud enough to cover you. You come in below them."}],"section":"The Approach","mode":"vote"},{"t":"say","text":"Either way the last stretch is the same: a gallery floored with timbers nobody has trusted in fifty years. Far beneath them, in the dark, is the river.","section":"The Approach"},{"t":"approach","title":"THE ROTTEN GALLERY","ways":[{"by":"By the passage","attr":"Aim","verb":"pick out, from above and by their own torchlight, the boards that will still bear weight"},{"by":"By the mouth","attr":"Agility","verb":"cross the timbers without a sound"}],"reward":"+500g · **and the party strikes first**","fail":"a timber cracks like a dropped plate, and **they strike first**","section":"The Approach"},{"t":"say","text":"You are among them before a single head turns.","cond":{"on":"approach","pass":true},"section":"The Approach"},{"t":"say","text":"Every torch in the mine swings your way.","cond":{"on":"approach","pass":false},"section":"The Approach"},{"t":"section","title":"The Battle","section":"The Battle"},{"t":"say","text":"{N} of them, between you and a small shape on the floor at the back of the gallery. Not one of them says a word.","section":"The Battle"},{"t":"say","text":"**This is a Battle. All of you fight at once, and it ends when the last enemy falls.**","section":"The Battle"},{"t":"battle","name":"MINE GUARD","firstLines":["You strike first.","He strikes first."],"desc":"","section":"The Battle"},{"t":"say","text":"It is over.\n\nA dropped torch rolls a little way on the boards and stops. Then there is no sound in the mine but the river.\n\nShe is at the back of the gallery with her wrists tied, and she is humming. A counting song, very quietly, the way you hum to keep from crying.\n\nWhoever reaches her first kneels slowly, so as not to loom over her. The knots are small and hard. Whoever tied them has tied a great many. They take a long time, and all that time she does not look away from your hands.\n\nShe does not stop when the ropes come off. She hums it all the way out into the air.\n\nOutside, after the mine, the evening is cold and very wide. She stands in it with her face turned up to the sky, breathing, still humming.\n\nYou have been saying her name for three days. Now you can see her. Tamsin is about nine.\n\nThere is a small cut across her palm. It has been bound in clean white linen. Somebody took the time.","section":"The Battle"},{"t":"section","title":"Notice","section":"Notice"},{"t":"notice","lines":{"Might":"They hit hard enough to drive you back, and never once hard enough to finish it.","Agility":"There is one more bedroll in this gallery than there are men on the floor.","Intellect":"Nobody in a mine has clean linen by accident. Somebody brought it here for this.","Charm":"She has stopped humming only once: when the lamp swung toward the end of the tunnel, and what lies there.","Craft":"Half the pit-props are new timber. Somebody has been keeping this place standing.","Aim":"Through the mine mouth, on the far bank: a horse, tied, saddled.","floor":"From down here you can see light between the gallery''s floorboards, and it is not torchlight: it is the river, a long way below, catching the torches."},"section":"Notice"},{"t":"say","text":"Look closer, if you like. It is a roll, and a miss costs nothing.","section":"Notice"},{"t":"act","label":"LOOK CLOSER","section":"Notice"},{"t":"lookCloser","lines":{"Might":"And the one in front of you kept glancing back at the girl. He was guarding her from the fight.","Agility":"The blanket is still warm.","Intellect":"It was cut with a knife, cleanly, from a longer piece. There is more of it somewhere.","Charm":"She will not look at it. She will look at you instead, and count.","Craft":"The newest prop was cut this week.","Aim":"It is facing away, and somebody has just untied it."},"section":"Notice"},{"t":"section","title":"The United Effort","section":"The United Effort"},{"t":"say","text":"The way on is back across the gallery. {RISK} is three steps ahead of you when the floor gives.\n\nThere is no warning. A timber that has waited fifty years goes all at once. {RISK} drops through it to the chest and stops there, jammed, arms flung wide over boards that are already splitting. Below {RISK}''s boots there is nothing but the sound of the river, a long way down in the dark.\n\nNobody can walk out there. The boards that are holding {RISK} will not hold a second pair of feet.\n\nA rope is no use. {RISK}''s two arms are all that is holding {RISK} up, and neither can let go to catch one.\n\nOne of you can go out flat, on your belly, with the rest standing on the stone at the gallery''s edge and holding your ankles, and haul. An arm has one haul like that in it. Then the next of you.\n\n**This is a United Effort. One job, and you take it in turns.**","section":"The United Effort"},{"t":"say","text":"It is you. You are jammed to the chest over the dark, and nobody is coming. Splinters bite your palms. The river''s cold breath comes up past your legs. You get an elbow onto sounder wood, a hand''s breadth at a time.","cond":{"on":"alone"},"section":"The United Effort"},{"t":"ue","section":"The United Effort"},{"t":"ueEnd","won":true,"section":"The United Effort"},{"t":"say","text":"{RISK} comes up out of the hole all at once, and you all go down together on the stone, gasping. You go round by the wall after that, one at a time, where the stone carries the boards.\n\nBehind the place where they held her, the tunnel ends in a slab of fallen roof as big as a barn door. Cold air breathes round its edges from a room beyond. It takes all of you, and it goes up in one heave. The room beyond has not been walked in: the dust lies as it fell.","cond":{"on":"ue","won":true},"section":"The United Effort"},{"t":"ueEnd","won":false,"section":"The United Effort"},{"t":"say","text":"The last board goes, and {RISK} goes with it. The dark takes the sound.\n\nYou find {RISK} where the river brings out what the mine drops: at the drowned mouth, grey, coughing, wrapped round a pit-prop, alive.\n\nIt is an hour before all of you are together again, and another before the hole is bridged with what timber is left.\n\nBehind the place where they held her, the tunnel ends in a slab of fallen roof as big as a barn door, with a room beyond. It takes all of you to lift it, and nobody is careful. You go in tired, wet and all at once, and the floor is a mess of your own bootprints before anyone thinks to look at it.\n\nWhatever the dust in there could have told you, it will not tell you now.","cond":{"on":"ue","won":false},"section":"The United Effort"},{"t":"section","title":"The discovery","section":"The discovery"},{"t":"say","text":"The room is small, square, and cut by hands a very long time ago. It is dry: the first dry air since the river. Your torches burn straight up in it. Nothing drips. The river, which has been in your ears all night, cannot be heard in here at all.\n\nThe map ended at a mark. Here is the mark.\n\nIt is cut into the chamber wall at the height of your chest: the shape from Meira''s rubbing, the shape at the end of the map. The burned scrap, held up to it, fits, as you knew it would.\n\nBut the mark is not a carving. It is a hole. Something sat in it, something made to that shape, and it is gone.","section":"The discovery"},{"t":"say","text":"The dust on the rim has settled again. Whatever was here was lifted out. Not tonight. Not centuries ago either.","cond":{"on":"ue","won":true},"section":"The discovery"},{"t":"say","text":"There was dust on the rim. Your own sleeves have wiped it. When this was emptied, nobody can now say.","cond":{"on":"ue","won":false},"section":"The discovery"},{"t":"say","text":"Under the empty place, scratched into the stone itself: **four names.**\n\nNone of them is yours. The first is Tamsin''s.\n\nThe scratches are rough and uneven, made with a knife point and no care. Somebody bends close with a torch and reads them through once, in silence. Nobody reads them aloud.","section":"The discovery"},{"t":"section","title":"The turn","section":"The turn"},{"t":"turn","question":"*Your names were on a list. So are these. What is different about them?*","section":"The turn","nudge":"*Look at the first name again.*","answer":"They are children''s names."},{"t":"say","text":"**This was never about you.**","alone":true,"section":"The turn"},{"t":"say","text":"Then why were your names on that list?\n\nThe wall does not say.","alone":true,"section":"The turn"},{"t":"section","title":"The Cliffhanger","section":"The Cliffhanger"},{"t":"say","text":"The chamber is very still.\n\nIn the lamplight, Garrick counts the names twice, silent.\n\n*\"Three more,\"* he says finally.\n\nAnd from the mine mouth, far behind you: hooves. One horse, already at a full gallop, going away.\n\nBy the time anyone reaches the mine mouth there is nothing to see but the dark, and the sound of it fading.","section":"The Cliffhanger"},{"t":"summary","lines":["**THE MINE** · Gathering 1","{EARNED}","The party: Battle {battle} · the drop: {ue:{RISK} hauled out|{RISK} fell}","You learned: **Tamsin is alive.** Something was taken from that wall before you came. Her name is scratched beneath it, with three more.","Tomorrow: **three names, and somebody who knows which is next**"],"section":"The Cliffhanger"}],"ue":{"success":{"0":["{RISK} comes out of the hole like a cork, and the two of you are dragged back across the boards by the ankles, fast, onto stone."],"1":["{RISK} is out to the hips, lying along a beam you would not have trusted with a cat.","One leg is up. {RISK} is laughing, or something like it."],"2":["{RISK}''s ribs are clear of the hole. The boards complain, and hold.","You have {RISK} by the belt. There is a knee on the edge, then not, then there again."],"3":["You get a fistful of {RISK}''s collar and pull until your shoulder cracks. {RISK} comes up a hand''s breadth: enough to get one elbow onto sounder wood.","Another hand''s breadth. {RISK}''s other arm is over the timber now."]},"fail":{"0":["The boards go, all of them, and {RISK} goes with them into the dark. A long moment. Then, far below, water."],"1":["{RISK}''s arms are shaking, and there is blood running off one elbow into the dark.","{RISK} has stopped looking at any of you, and is looking down."],"2":["A timber-end works loose overhead and comes down across {RISK}''s shoulder. {RISK} goes white.","The boards shift, and close on {RISK}''s chest like a hand. For a moment {RISK} cannot get a breath."],"3":["The board under your chest cracks like a dropped plate, and you are hauled back by the ankles. A broken end swings round and takes the skin off {RISK}''s ribs.","Something gives under {RISK}''s arm. A splinter as long as a knife goes in above the elbow. {RISK} says nothing."]},"between":["Somewhere behind you, out in the air, a counting song is still going.","Below {RISK}''s boots, the river goes on saying the same thing.","For a while now there has been no sound but breathing, and wood."]}}'::jsonb)
on conflict (series_id, season_number, week) do update set data = excluded.data;
